import com.example.AuthManager;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class AuthManagerTest {

    @Test
    public void testRegisterValidUser() {
        AuthManager authManager = new AuthManager();
        assertTrue(authManager.register("user123", "Password123"));
    }

    @Test
    public void testRegisterNullUsername() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.register(null, "Password123"));
    }

    @Test
    public void testRegisterNullPassword() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.register("user123", null));
    }

    @Test
    public void testRegisterShortUsername() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.register("us", "Password123"));
    }

    @Test
    public void testRegisterExistingUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertFalse(authManager.register("user123", "Password123"));
    }

    @Test
    public void testRegisterInvalidPassword() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.register("user123", "password"));
    }

    @Test
    public void testLoginValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertTrue(authManager.login("user123", "Password123"));
    }

    @Test
    public void testLoginNullUsername() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.login(null, "Password123"));
    }

    @Test
    public void testLoginNullPassword() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.login("user123", null));
    }

    @Test
    public void testLoginInvalidPassword() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertFalse(authManager.login("user123", "password"));
    }

    @Test
    public void testLogoutValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        authManager.login("user123", "Password123");
        assertTrue(authManager.logout("user123"));
    }

    @Test
    public void testLogoutInvalidUser() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.logout("user123"));
    }

    @Test
    public void testIsLoggedInValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        authManager.login("user123", "Password123");
        assertTrue(authManager.isLoggedIn("user123"));
    }

    @Test
    public void testIsLoggedInInvalidUser() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.isLoggedIn("user123"));
    }

    @Test
    public void testResetPasswordValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertTrue(authManager.resetPassword("user123", "Password123", "NewPassword123"));
    }

    @Test
    public void testResetPasswordInvalidOldPassword() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertFalse(authManager.resetPassword("user123", "password", "NewPassword123"));
    }

    @Test
    public void testResetPasswordInvalidNewPassword() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertFalse(authManager.resetPassword("user123", "Password123", "newpassword"));
    }

    @Test
    public void testGetStatusRegisteredUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertEquals("OFFLINE", authManager.getStatus("user123"));
    }

    @Test
    public void testGetStatusUnregisteredUser() {
        AuthManager authManager = new AuthManager();
        assertEquals("NOT_REGISTERED", authManager.getStatus("user123"));
    }

    @Test
    public void testGetStatusLoggedInUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        authManager.login("user123", "Password123");
        assertEquals("ONLINE", authManager.getStatus("user123"));
    }

    @Test
    public void testGetUserCount() {
        AuthManager authManager = new AuthManager();
        assertEquals(0, authManager.getUserCount());
        authManager.register("user123", "Password123");
        assertEquals(1, authManager.getUserCount());
    }

    @Test
    public void testClearAll() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        authManager.login("user123", "Password123");
        authManager.clearAll();
        assertEquals(0, authManager.getUserCount());
        assertFalse(authManager.isLoggedIn("user123"));
    }

    @Test
    public void testDeleteUserValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertTrue(authManager.deleteUser("user123", "Password123"));
    }

    @Test
    public void testDeleteUserInvalidPassword() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertFalse(authManager.deleteUser("user123", "password"));
    }

    @Test
    public void testUpdateUsernameValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertTrue(authManager.updateUsername("user123", "newuser123"));
    }

    @Test
    public void testUpdateUsernameInvalidNewUsername() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        authManager.register("newuser123", "Password123");
        assertFalse(authManager.updateUsername("user123", "newuser123"));
    }

    @Test
    public void testExportData() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        assertNotNull(authManager.exportData());
    }

    @Test
    public void testIsAdminValidAdmin() {
        AuthManager authManager = new AuthManager();
        assertTrue(authManager.isAdmin("admin"));
    }

    @Test
    public void testIsAdminInvalidAdmin() {
        AuthManager authManager = new AuthManager();
        assertFalse(authManager.isAdmin("user123"));
    }

    @Test
    public void testGenerateTokenValidUser() {
        AuthManager authManager = new AuthManager();
        authManager.register("user123", "Password123");
        authManager.login("user123", "Password123");
        assertNotNull(authManager.generateToken("user123"));
    }

    @Test
    public void testGenerateTokenInvalidUser() {
        AuthManager authManager = new AuthManager();
        assertNull(authManager.generateToken("user123"));
    }
}
